// Step 2: Preprocess Email Data
const item = $json;

// Extract Sender, Subject, Body, and Metadata safely
const sender = item.from?.value?.[0]?.address || item.from?.text || item.from || 'Unknown Sender';
const senderName = item.from?.value?.[0]?.name || item.senderName || sender;
const subject = item.subject || '(No Subject)';
const body = (item.text || item.snippet || item.html || '(Empty Body)').replace(/<[^>]*>?/gm, ''); // Strip basic HTML tags if any
const messageId = item.id || item.messageId;
const threadId = item.threadId;
const dateReceived = item.date || new Date().toISOString();

// Formatted prompt text input as specified
const formattedPrompt = `Sender: ${sender}\nSubject: ${subject}\nBody: ${body.substring(0, 3000)}`;

return {
  json: {
    messageId,
    threadId,
    sender,
    senderName,
    subject,
    body,
    formattedPrompt,
    dateReceived
  }
};

