// Step 4: Parse Gemini Response & Fallback Handling
const input = $json;
let classification = "IMPORTANT"; // Default safety fallback to prevent accidental deletion
let reason = "Default fallback applied due to API error or parsing issue.";
let isApiError = false;

try {
  if (input.error || input.errorOutput) {
    isApiError = true;
    reason = `Gemini API Call Failed: ${JSON.stringify(input.error || input.errorOutput)}`;
  } else {
    const candidateText = input.candidates?.[0]?.content?.parts?.[0]?.text;
    if (candidateText) {
      const cleanText = candidateText.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();
      const parsed = JSON.parse(cleanText);
      classification = parsed.classification || "IMPORTANT";
      reason = parsed.reason || "No explicit reason provided.";
    }
  }
} catch (e) {
  isApiError = true;
  reason = `Failed to parse Gemini output: ${e.message}`;
}

// Enforce valid enum
if (classification !== "IMPORTANT" && classification !== "NOT_IMPORTANT") {
  classification = "IMPORTANT";
}

// Retrieve original email item from Preprocess node
const emailData = $("Preprocess Email Data").item.json;

return {
  json: {
    ...emailData,
    classification,
    reason,
    isApiError
  }
};

// Audit Log for Trashed/Unimportant Email
const logData = {
  timestamp: new Date().toISOString(),
  action: "MOVE_TO_TRASH",
  messageId: $json.messageId,
  sender: $json.sender,
  subject: $json.subject,
  reason: $json.reason,
  status: "COMPLETED"
};

console.log("[AUDIT LOG] Email Trashed Successfully:", JSON.stringify(logData, null, 2));

return {
  json: logData
};

