  timestamp: new Date().toISOString(),
  executionId: $execution.id,
  workflowId: $workflow.id,
  workflowName: $workflow.name,
  errorDetails: $json.execution?.error || $json.error || "Workflow execution failure",
  safetyAction: "Email preserved in inbox / not deleted."
};

console.error("[WORKFLOW ERROR AUDIT] Execution stored for debugging:", JSON.stringify(errorLog, null, 2));

return {
  json: errorLog
};
